<?php
namespace ProjectPress\Admin\Manager\Projects;use ProjectPress\Includes\Functions\Helpers\RequestHelper;use ProjectPress\Includes\Project\Communication\NotificationRepository;use ProjectPress\Includes\Project\Communication\NotificationService;use ProjectPress\Includes\Project\Core\Project;use ProjectPress\Includes\Project\Core\ProjectPermissions;use ProjectPress\Includes\Project\People\TimeSheetRepository;use ProjectPress\Includes\Project\People\TimeSheetService;use ProjectPress\Includes\Project\ProjectManager as DomainProjectManager;use WP_Error;if(!defined('ABSPATH')){exit;}final class PeopleCommunication{private DomainProjectManager$projects;private ProjectPermissions$permissions;public function __construct(?DomainProjectManager$projects=null,?ProjectPermissions$permissions=null){$this->projects=$projects??DomainProjectManager::get_instance();$this->permissions=$permissions??new ProjectPermissions();}public function render(Project$project):void{$times=(new TimeSheetRepository())->for_project($project->get_id());$notes=(new NotificationRepository())->for_project($project->get_id());$can=$this->permissions->can_edit($project);?><div class="row g-4"><div class="col-xl-6"><div class="card card-body"><h2 class="h4"><?php esc_html_e('Timesheets','projectpress');?></h2><?php foreach($times as$item):?><div class="border rounded p-2 mb-2"><strong><?php echo esc_html(sprintf(__('%1$d minutes · User %2$d','projectpress'),$item->get_minutes(),$item->get_user_id()));?></strong><?php if($can):?><?php $this->delete_form('timesheet',$project->get_id(),$item->get_id());?><?php endif;?></div><?php endforeach;?><?php if($can):?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="projectpress_workspace_people_save"/><input type="hidden" name="project_id" value="<?php echo esc_attr((string)$project->get_id());?>"/><input type="hidden" name="type" value="timesheet"/><?php wp_nonce_field('projectpress_workspace_people_save');?><label class="form-label"><?php esc_html_e('User ID','projectpress');?></label><input class="form-control" type="number" min="1" name="user_id" required/><label class="form-label mt-2"><?php esc_html_e('Minutes','projectpress');?></label><input class="form-control" type="number" min="1" name="minutes" required/><label class="form-label mt-2"><?php esc_html_e('Work date','projectpress');?></label><input class="form-control" type="date" name="work_date"/><label class="form-label mt-2"><?php esc_html_e('Description','projectpress');?></label><textarea class="form-control" name="description"></textarea><button class="btn btn-primary mt-3" type="submit"><?php esc_html_e('Add Time','projectpress');?></button></form><?php endif;?></div></div><div class="col-xl-6"><div class="card card-body"><h2 class="h4"><?php esc_html_e('Project Notifications','projectpress');?></h2><?php foreach($notes as$item):?><div class="border rounded p-2 mb-2"><strong><?php echo esc_html(sprintf(__('User %d','projectpress'),$item->get_recipient_id()));?></strong><div><?php echo esc_html($item->get_message());?></div><?php if($can):?><?php $this->delete_form('notification',$project->get_id(),$item->get_id());?><?php endif;?></div><?php endforeach;?><?php if($can):?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="projectpress_workspace_people_save"/><input type="hidden" name="project_id" value="<?php echo esc_attr((string)$project->get_id());?>"/><input type="hidden" name="type" value="notification"/><?php wp_nonce_field('projectpress_workspace_people_save');?><label class="form-label"><?php esc_html_e('Recipient User ID','projectpress');?></label><input class="form-control" type="number" min="1" name="recipient_id" required/><label class="form-label mt-2"><?php esc_html_e('Message','projectpress');?></label><textarea class="form-control" name="message" required></textarea><button class="btn btn-primary mt-3" type="submit"><?php esc_html_e('Add Notification','projectpress');?></button></form><?php endif;?></div></div></div><?php }private function delete_form(string$type,int$project_id,int$id):void{?><form class="mt-2" method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="projectpress_workspace_people_delete"/><input type="hidden" name="project_id" value="<?php echo esc_attr((string)$project_id);?>"/><input type="hidden" name="type" value="<?php echo esc_attr($type);?>"/><input type="hidden" name="record_id" value="<?php echo esc_attr((string)$id);?>"/><?php wp_nonce_field('projectpress_workspace_people_delete');?><button class="btn btn-sm btn-outline-danger" type="submit"><?php esc_html_e('Delete','projectpress');?></button></form><?php }public function handle_save():void{check_admin_referer('projectpress_workspace_people_save');$id=RequestHelper::integer($_POST,'project_id',0);$type=RequestHelper::key($_POST,'type','');if('timesheet'===$type){$repo=new TimeSheetRepository();$result=(new TimeSheetService($repo,$this->projects->repository(),$this->permissions))->create($id,array('user_id'=>RequestHelper::integer($_POST,'user_id',0),'minutes'=>RequestHelper::integer($_POST,'minutes',0),'work_date'=>RequestHelper::text($_POST,'work_date',''),'description'=>RequestHelper::text($_POST,'description','')));}elseif('notification'===$type){$repo=new NotificationRepository();$result=(new NotificationService($repo,$this->projects->repository(),$this->permissions))->create($id,array('recipient_id'=>RequestHelper::integer($_POST,'recipient_id',0),'message'=>RequestHelper::text($_POST,'message','')));}else{$result=new WP_Error('projectpress_people_type_invalid',__('Invalid record type.','projectpress'));}$this->redirect($id,$result);}public function handle_delete():void{check_admin_referer('projectpress_workspace_people_delete');$id=RequestHelper::integer($_POST,'project_id',0);$type=RequestHelper::key($_POST,'type','');if('timesheet'===$type){$repo=new TimeSheetRepository();$record=$repo->find(RequestHelper::integer($_POST,'record_id',0));$result=$record&&$record->get_project_id()===$id?(new TimeSheetService($repo,$this->projects->repository(),$this->permissions))->delete($record):new WP_Error('projectpress_timesheet_not_found',__('Timesheet not found.','projectpress'));}else{$repo=new NotificationRepository();$record=$repo->find(RequestHelper::integer($_POST,'record_id',0));$result=$record&&$record->get_project_id()===$id?(new NotificationService($repo,$this->projects->repository(),$this->permissions))->delete($record):new WP_Error('projectpress_notification_not_found',__('Notification not found.','projectpress'));}$this->redirect($id,$result);}private function redirect(int$id,$result):void{$url=add_query_arg(array('page'=>'projectpress','group'=>'projects','project_id'=>absint($id),'tab'=>'people-communication'),admin_url('admin.php'));$url=is_wp_error($result)?add_query_arg('project_error',rawurlencode($result->get_error_message()),$url):add_query_arg('project_saved','1',$url);wp_safe_redirect($url);exit;}}
